1	package leasekv
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"maps"
7		"slices"
8		"sync"
9	)
10	
11	// Disk is the store's log file. Bytes written with Append are durable only after Sync returns
12	// nil. A Disk belongs to one start of the store.
13	type Disk interface {
14		ReadAll() ([]byte, error)
15		Append(p []byte) error
16		Sync() error
17	}
18	
19	// Store keeps the list of every key in a write-ahead log on its disk. It syncs the log before
20	// every reply, so a reply only describes durable state. It remembers the last write of every
21	// client in the same log, so a write sent again is applied once. It rejects requests whose epoch
22	// is below the highest epoch it has seen.
23	type Store struct {
24		Conn Conn
