11	)
12	
13	// network delivers each message after a random delay of 1 to 5 ms. During a partition it drops
14	// messages between nodes on different sides, at send time and at delivery. It drops messages to
15	// a node that is down and from an earlier start of a node.
16	type network struct {
17		mu     sync.Mutex
18		handle map[string]func(from string, msg any) // nil while the node is down
19		start  map[string]int                        // how many times each node started
20		side   map[string]int                        // nil when there is no partition
21	}
22	
23	func newNetwork() *network {
24		return &network{handle: map[string]func(string, any){}, start: map[string]int{}}
25	}
26	
27	// conn is one start of one node.
28	type conn struct {
29		nw    *network
30		from  string
31		start int
32	}
33	
34	func (c conn) Send(to string, msg any) {
35		nw := c.nw
36		nw.mu.Lock()
37		ok := nw.start[c.from] == c.start && nw.handle[c.from] != nil && nw.connected(c.from, to)
38		nw.mu.Unlock()
39		if !ok {
40			return
41		}
42		time.AfterFunc(time.Millisecond+rand.N(4*time.Millisecond), func() {
43			nw.mu.Lock()
44			h := nw.handle[to]
45			if !nw.connected(c.from, to) {
46				h = nil
47			}
48			nw.mu.Unlock()
49			if h != nil {
50				h(c.from, msg)
51			}
52		})
53	}
54	
55	func (nw *network) connected(a, b string) bool { return nw.side == nil || nw.side[a] == nw.side[b] }
56	
57	// next returns the conn of the next start of name. It sends nothing until up.
58	func (nw *network) next(name string) conn {
59		nw.mu.Lock()
60		defer nw.mu.Unlock()
61		return conn{nw: nw, from: name, start: nw.start[name] + 1}
62	}
63	
64	// up starts name: messages to it go to h.
65	func (nw *network) up(name string, h func(string, any)) {
66		nw.mu.Lock()
67		defer nw.mu.Unlock()
68		nw.start[name]++
69		nw.handle[name] = h
70	}
71	
72	func (nw *network) down(name string) {
73		nw.mu.Lock()
74		defer nw.mu.Unlock()
75		nw.handle[name] = nil
76	}
77	
78	func (nw *network) partition(side map[string]int) {
79		nw.mu.Lock()
80		defer nw.mu.Unlock()
81		nw.side = side
82	}
83	
84	// disk is the store's disk. A crash keeps the synced bytes only, and the files of earlier starts
85	// stop working.
86	type disk struct {
87		mu     sync.Mutex
88		data   []byte
89		synced int
90		start  int
91	}
92	
93	type diskFile struct {
94		d     *disk
95		start int
96	}
97	
98	func (d *disk) open() *diskFile {
99		d.mu.Lock()
100		defer d.mu.Unlock()
101		return &diskFile{d: d, start: d.start}
102	}
103	
104	func (d *disk) crash() {
105		d.mu.Lock()
106		defer d.mu.Unlock()
107		d.data = d.data[:d.synced]
108		d.start++
109	}
110	
111	func (f *diskFile) do(op func(d *disk)) error {
112		f.d.mu.Lock()
113		defer f.d.mu.Unlock()
114		if f.start != f.d.start {
115			return errStale
116		}
117		op(f.d)
118		return nil
119	}
120	
121	func (f *diskFile) ReadAll() (b []byte, err error) {
122		err = f.do(func(d *disk) { b = slices.Clone(d.data) })
123		return b, err
124	}
125	
126	func (f *diskFile) Append(p []byte) error {
127		return f.do(func(d *disk) { d.data = append(d.data, p...) })
128	}
129	
130	func (f *diskFile) Sync() error { return f.do(func(d *disk) { d.synced = len(d.data) }) }
131	
132	type staleError struct{}
133	
134	func (staleError) Error() string { return "stale file" }
135	
136	var errStale error = staleError{}
137	
138	// plan is the fault plan: crashes of s1, s2 or the store, one at a time, and partitions that put
139	// s1 and s2 on different sides and every other node on a random side. A rule starts a fault
140	// after a random gap of Every/2 to 3*Every/2, and the fault lasts min to max. Partitions do not
141	// overlap.
142	type plan struct {
143		crashEvery, crashMin, crashMax             time.Duration
144		partitionEvery, partitionMin, partitionMax time.Duration
145	}
146	
147	// cluster is one run of the service.
148	type cluster struct {
149		nw      *network
150		disk    *disk
151		origin  time.Time
152		lock    *leasekv.Lock
153		clients []*leasekv.Client
154	
155		mu        sync.Mutex
156		store     *leasekv.Store
157		cancel    map[string]context.CancelFunc
158		down      map[string]bool
159		splitDone bool // a partition is active
160		recovered bool
161		err       error
162	}
163	
164	var crashable = []string{"s1", "s2", "store"}
165	
166	func newCluster() *cluster {
167		c := &cluster{nw: newNetwork(), disk: &disk{}, origin: time.Now(),
168			cancel: map[string]context.CancelFunc{}, down: map[string]bool{}}
169		c.lock = &leasekv.Lock{Conn: c.nw.next("lock"), TTL: ttl}
170		c.nw.up("lock", c.lock.Handle)
171		c.mu.Lock()
